WITH remaining_keys AS (SELECT location, id FROM departments INTERSECT ALL SELECT location, id FROM departments WHERE dept_name != 'Marketing'), verified AS (SELECT s.* FROM departments s INNER JOIN remaining_keys k ON s.location = k.location AND s.id = k.id) SELECT dept_name, PERCENTILE_APPROX(budget, 0.5) AS budget_p50, STDDEV_SAMP(budget) AS budget_stddev FROM verified GROUP BY 1;
